export const DISPUTE_REASONS = [
  "Not finished",
  "Missing or wrong items",
  "Damage",
  "Late",
  "Other",
];

export function disputeText(reason, details) {
  const d = (details || "").trim();
  if (!reason) return d;
  return d ? `${reason}: ${d}` : reason;
}

/* The server's own rule for a dispute's reason, mirrored so the app refuses
   it BEFORE sending (backend controllers/order/report_dispute.js
   dispute_order, owner ruling 2026-09-14: "We can't ever allow a Requester to
   dispute an order without a reason"): the reason, trimmed, must be at least
   MIN_DISPUTE_REASON characters, else a 400 with the sentence below.

   The guided form sends the chip and the details as ONE string (disputeText),
   so the rule is applied to that string, exactly as the server reads it. A
   chip alone is often short of it ("Late" = 4, "Damage" = 6, "Other" = 5):
   before this the app sent it, the server refused it, and the requester saw
   the refusal only after the round trip (audit E, found in passing 3).

   ⛔ Keep both in step with the server. The sentence is the server's, word for
   word, so the requester reads the same thing whichever side stops it. */
export const MIN_DISPUTE_REASON = 10;
export const DISPUTE_REASON_REQUIRED =
  "Please tell us what went wrong before opening a dispute. Your Gopher " +
  "only sees what you write here, so a short sentence about the problem " +
  "is enough — for example what was missing, wrong or damaged.";

/** The server's refusal for this dispute text, or null when it would pass. */
export function disputeReasonProblem(text) {
  return String(text || "").trim().length < MIN_DISPUTE_REASON
    ? DISPUTE_REASON_REQUIRED
    : null;
}

const DAY_MS = 24 * 60 * 60 * 1000;

/** "Available in 19 h 26 min" | "Available now" | the rule in words. */
export function escalationLabel(disputedAt, now = Date.now()) {
  const t = disputedAt ? new Date(disputedAt).getTime() : NaN;
  if (!Number.isFinite(t)) return "Available 24 hours after the dispute opened";
  const left = t + DAY_MS - now;
  if (left <= 0) return "Available now";
  const h = Math.floor(left / 3600000);
  const m = Math.ceil((left % 3600000) / 60000);
  return h ? `Available in ${h} h ${m} min` : `Available in ${m} min`;
}
